export const searchMovieByName = (query) => {
  if (!query) return null;
  const q = query.toLowerCase().trim();
  return expandedMoviesDatabase.find((m) => m.name.toLowerCase().includes(q)) || null;
};

export const searchMovies = (query) => {
  if (!query) return [];
  const q = query.toLowerCase().trim();
  return expandedMoviesDatabase.filter((m) => m.name.toLowerCase().includes(q));
};

export const allCategories = Array.from(
  new Set(expandedMoviesDatabase.flatMap((m) => m.categories))
).sort();

export const allRatings = Array.from(
  new Set(expandedMoviesDatabase.map((m) => m.edad).filter(Boolean))
).sort();

export default expandedMoviesDatabase;
